// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (POST /chat/messages/{messageId}/report)
	ReportMessage(ctx context.Context, request ReportMessageRequestObject) (ReportMessageResponseObject, error)

	// (GET /chat/rooms)
	ListRooms(ctx context.Context, request ListRoomsRequestObject) (ListRoomsResponseObject, error)
	// JoinRoom Verified members join group rooms themselves; never automatic.
	// (POST /chat/rooms/{roomId}/join)
	JoinRoom(ctx context.Context, request JoinRoomRequestObject) (JoinRoomResponseObject, error)

	// (POST /chat/rooms/{roomId}/leave)
	LeaveRoom(ctx context.Context, request LeaveRoomRequestObject) (LeaveRoomResponseObject, error)
	// ListMessages History after a sequence number (resume) or before it (scroll back).
	// (GET /chat/rooms/{roomId}/messages)
	ListMessages(ctx context.Context, request ListMessagesRequestObject) (ListMessagesResponseObject, error)
	// SendMessage Send a text message (also possible over the WebSocket). The client message ID makes it idempotent.
	// (POST /chat/rooms/{roomId}/messages)
	SendMessage(ctx context.Context, request SendMessageRequestObject) (SendMessageResponseObject, error)
	// ModerateRoom Room moderation by staff, or by the room's mentor with limited actions (hide, mute_1h). Audited.
	// (POST /chat/rooms/{roomId}/moderation)
	ModerateRoom(ctx context.Context, request ModerateRoomRequestObject) (ModerateRoomResponseObject, error)

	// (PUT /chat/rooms/{roomId}/mute)
	SetRoomMute(ctx context.Context, request SetRoomMuteRequestObject) (SetRoomMuteResponseObject, error)
	// DeleteMessageLegalHold Release a message from legal hold. Staff moderator or admin, MFA. Audited.
	// (DELETE /staff/chat/messages/{messageId}/legal-hold)
	DeleteMessageLegalHold(ctx context.Context, request DeleteMessageLegalHoldRequestObject) (DeleteMessageLegalHoldResponseObject, error)
	// PutMessageLegalHold Put a message under legal hold (ADR-0019). Staff moderator or admin, MFA. Audited.
	// (PUT /staff/chat/messages/{messageId}/legal-hold)
	PutMessageLegalHold(ctx context.Context, request PutMessageLegalHoldRequestObject) (PutMessageLegalHoldResponseObject, error)
	// StaffListRooms Group rooms with member counts and mentors, for mentor assignment. Staff moderator or admin, MFA.
	// (GET /staff/chat/rooms)
	StaffListRooms(ctx context.Context, request StaffListRoomsRequestObject) (StaffListRoomsResponseObject, error)
	// RemoveRoomMentor Remove a mentor from a group room. Staff moderator or admin, MFA. Audited.
	// (DELETE /staff/chat/rooms/{roomId}/mentors/{memberId})
	RemoveRoomMentor(ctx context.Context, request RemoveRoomMentorRequestObject) (RemoveRoomMentorResponseObject, error)
	// AssignRoomMentor Assign a mentor to a group room. Staff moderator or admin, MFA. Audited.
	// (PUT /staff/chat/rooms/{roomId}/mentors/{memberId})
	AssignRoomMentor(ctx context.Context, request AssignRoomMentorRequestObject) (AssignRoomMentorResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

